<section class="section public-profile"><div class="profile-hero"><div class="freelancer-avatar large"><?=e(mb_substr($profile['display_name'],0,1))?></div><div><div class="eyebrow">پروفایل عمومی فریلنسر</div><h1><?=e($profile['display_name'])?></h1><p><?=e($profile['headline']?:'متخصص مستقل')?> · <?=e($profile['location']?:'بین‌المللی')?></p><span class="status status-<?=e($profile['availability'])?>"><?=e($profile['availability']==='available'?'آماده همکاری':'مشغول')?></span></div><a class="button" href="<?=url('/register?role=employer')?>">Hire Me ↗</a></div><div class="profile-grid"><section class="dash-card"><h2>درباره من</h2><p><?=nl2br(e($profile['bio']?:'این فریلنسر هنوز توضیحی اضافه نکرده است.'))?></p><h2>مهارت‌ها</h2><div class="skill-list"><?php foreach($skills as $s):?><span class="skill-tag"><?=e($s['name'])?></span><?php endforeach;?></div><h2>رزومه</h2><?php foreach($experiences as $x):?><div class="timeline-item"><strong><?=e($x['job_title'])?> · <?=e($x['company_name'])?></strong><p><?=e($x['description']?:'')?></p></div><?php endforeach;?><?php foreach($educations as $x):?><div class="timeline-item"><strong><?=e($x['degree'])?> · <?=e($x['institution'])?></strong></div><?php endforeach;?></section><section><h2>نمونه‌کارها</h2><div class="portfolio-grid"><?php foreach($portfolios as $p):?><a class="portfolio-card" href="<?=url('/portfolio?slug='.rawurlencode($p['slug']))?>"><h3><?=e($p['title'])?></h3><p><?=e($p['description'])?></p><small><?=e($p['technologies']?:'')?></small></a><?php endforeach;?></div><?php if(!$portfolios):?><div class="dash-card empty-state">هنوز نمونه‌کاری منتشر نشده است.</div><?php endif;?></section></div></section>